def connect_sharepoint_data_sight(name, client_id, client_secret, tenant_id, site_url, auto_sync):
    """Conecta SharePoint/OneDrive a Data Sight."""
    try:
        result = data_sight_integrations.connect_sharepoint(
            name=name,
            client_id=client_id,
            client_secret=client_secret,
            tenant_id=tenant_id,
            site_url=site_url if site_url else None,
            auto_sync=auto_sync
        )
        if result.get("success"):
            return f"âœ… {result.get('message', 'SharePoint conectado exitosamente')}\n\n**Connection ID:** `{result.get('connection_id')}`"
        else:
            return f"âŒ Error: {result.get('error', 'Error desconocido')}"
    except Exception as e:
        return f"âŒ Error: {str(e)}"


