def list_data_sight_connections():
    """Lista todas las conexiones de Data Sight."""
    try:
        connections = data_sight_integrations.list_connections()
        if not connections:
            return "ðŸ“‹ **No hay conexiones configuradas.**\n\nConecta un sistema desde las pestaÃ±as de arriba."
        
        lines = ["## ðŸ“‹ Conexiones Activas\n\n"]
        lines.append("| Nombre | Tipo | Estado | Ãšltima SincronizaciÃ³n |\n")
        lines.append("|--------|------|--------|------------------------|\n")
        
        for conn in connections:
            status_emoji = "âœ…" if conn["status"] == "active" else "âŒ" if conn["status"] == "error" else "âš ï¸"
            last_sync = conn.get("last_sync", "Nunca")
            if last_sync and last_sync != "Nunca":
                try:
                    from datetime import datetime
                    dt = datetime.fromisoformat(last_sync.replace("Z", "+00:00"))
                    last_sync = dt.strftime("%Y-%m-%d %H:%M")
                except:
                    pass
            
            lines.append(f"| {conn['name']} | {conn['system_type']} | {status_emoji} {conn['status']} | {last_sync} |\n")
            lines.append(f"| `{conn['connection_id']}` | Auto-sync: {'âœ…' if conn['auto_sync'] else 'âŒ'} | | |\n")
        
        return "".join(lines)
    except Exception as e:
        return f"âŒ Error listando conexiones: {str(e)}"


def sync_data_sight_connection(connection_id):
    """Sincroniza una conexiÃ³n especÃ­fica de Data Sight."""
    try:
        if not connection_id or not connection_id.strip():
            return "âŒ Por favor, ingresa un Connection ID vÃ¡lido."
        
        result = data_sight_integrations.sync_connection(connection_id.strip())
        
        if result.get("success"):
            files_count = result.get("files_processed", 0)
            if files_count > 0:
                return f"âœ… **SincronizaciÃ³n exitosa**\n\nðŸ“„ **Archivos procesados:** {files_count}\n\nLos documentos se han procesado automÃ¡ticamente con Data Sight."
            else:
                return f"âœ… **SincronizaciÃ³n completada**\n\nâ„¹ï¸ No se encontraron documentos nuevos para procesar."
        else:
            return f"âŒ Error: {result.get('error', 'Error desconocido')}"
    except Exception as e:
        return f"âŒ Error: {str(e)}"


