                    with gr.Row():
                        drive_max_files = gr.Slider(minimum=10, maximum=200, value=50, step=10, label="MÃ¡ximo de archivos")
                        sync_drive_btn = gr.Button("ðŸ“ SINCRONIZAR DRIVE", variant="primary", size="lg")
                    
