            def run_text_to_action(description, context_json, max_iter, provider):
                """Ejecuta text-to-action: genera cÃ³digo y lo ejecuta."""
                if not description or not description.strip():
                    return "", "", "", {}, "âš ï¸ Escribe una descripciÃ³n de lo que quieres hacer."
                
                # Crear agente con el provider seleccionado
                temp_agent = TextToAction(config)
                
                # Parsear contexto si estÃ¡ disponible
                context = None
                if context_json and context_json.strip():
                    try:
                        context = json.loads(context_json)
                    except:
                        context = None
                
                # Ejecutar acciÃ³n
                result = temp_agent.execute_action(
                    description=description,
                    context=context,
                    max_iterations=int(max_iter)
                )
                
                # Formatear salida
                code_display = result.get('code', '')
                explanation = result.get('explanation', '')
                output_text = result.get('output', '')
                result_data = result.get('result')
                error = result.get('error')
                
                # Construir status
                if result['success']:
                    status = f"âœ… **CÃ³digo ejecutado exitosamente**\n\n"
                    status += f"- Iteraciones: {len(result.get('iterations', []))}\n"
                    if output_text:
                        status += f"- Output generado: âœ…\n"
                    if result_data is not None:
                        status += f"- Resultado guardado: âœ…\n"
                else:
                    status = f"âŒ **Error ejecutando cÃ³digo**\n\n"
                    status += f"- Iteraciones intentadas: {len(result.get('iterations', []))}\n"
                    if error:
                        status += f"- Error: {error[:200]}...\n"
                
                # Agregar informaciÃ³n de iteraciones
                iterations = result.get('iterations', [])
                if len(iterations) > 1:
                    status += f"\n**Proceso de correcciÃ³n:**\n"
                    for iter_info in iterations:
                        iter_num = iter_info.get('iteration', 0)
                        exec_result = iter_info.get('execution', {})
                        if exec_result.get('success'):
                            status += f"- IteraciÃ³n {iter_num}: âœ… Ã‰xito\n"
                        else:
                            status += f"- IteraciÃ³n {iter_num}: âŒ Error corregido\n"
                
                # Formatear output con error si hay
                full_output = output_text
                if error:
                    full_output = f"{output_text}\n\nâŒ ERROR:\n{error}"
                
                return code_display, explanation, full_output, result_data if result_data is not None else {}, status
            
