    # CRÃTICO: Cloud Run solo permite escritura en /tmp
    cloud_port = os.environ.get("PORT")
    if cloud_port:
        # Configurar variables de entorno para usar /tmp
        os.environ["TMPDIR"] = "/tmp"
        os.environ["TMP"] = "/tmp"
        os.environ["TEMP"] = "/tmp"
        
        # Crear directorios necesarios en /tmp
        import tempfile
        tempfile.tempdir = "/tmp"
        
        # Crear directorios en /tmp con permisos correctos
        os.makedirs("/tmp/documents", exist_ok=True)
        os.makedirs("/tmp/data", exist_ok=True)
        
        # Asegurar permisos de escritura (Cloud Run usa usuario root, pero por si acaso)
        try:
            os.chmod("/tmp/documents", 0o777)
            os.chmod("/tmp/data", 0o777)
        except:
            pass
        
        print(f"âœ… Cloud Run detectado - Configurando /tmp para archivos")
        print(f"âœ… Directorios creados: /tmp/documents, /tmp/data")
    
    # Para ejecuciÃ³n local, Gradio usa el puerto 7860 por defecto
